class Student
{
    public string Name { get; }
    public List<int> Marks { get; } = new();
    public Student(string name) => Name = name;

    public void AddMark(int mark)
    {
        if (mark is < 0 or > 100) throw new ArgumentOutOfRangeException(nameof(mark));
        Marks.Add(mark);
    }
}

